
// AVISA - Marca del sistema (logo + textos)
var IMG_LT_PROTESTAS = 'data:image/jpeg;base64,';
var IMG_LT_REUNIONES = 'data:image/jpeg;base64,';
var IMG_LT_DOCUMENTOS = 'data:image/jpeg;base64,';
var IMG_LT_TUERCA = 'data:image/jpeg;base64,';

var LOGO_AVISA = 'data:image/jpeg;base64,';
var LOGO_AVISA_COMPACTA = 'data:image/jpeg;base64,';
function _inyectarEstilosAVISA() {
  if (document.getElementById('avisaStyles')) return;
  var css = ''
    // Realce del focus en los inputs del login (tu .login-card usa .fc input)
    + '.login-card .fc input:focus{border-color:#1A56A0 !important;box-shadow:0 0 0 4px rgba(26,86,160,.16) !important;}'
    + '.login-card .fc input{transition:border-color .18s, box-shadow .18s;height:44px;border-radius:9px;}'
    + '.login-card{animation:avCardIn .5s cubic-bezier(.2,.7,.2,1);}'
    + '@keyframes avCardIn{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}'
    // Boton de ingresar mas redondeado
    + '.login-card #btnLogin{border-radius:11px;height:46px;}'
    // Placa flotante para el logo del sidebar (integra el logo negativo sobre el fondo oscuro)
    + '.avisa-brand-plate{display:flex;align-items:center;justify-content:center;width:100%;margin:2px 0 10px;padding:12px 12px;background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.10);border-radius:12px;box-shadow:inset 0 1px 0 rgba(255,255,255,.06);box-sizing:border-box;}'
    + '.avisa-brand-plate img{display:block;width:100%;max-width:150px;height:auto;}'
    // En modo colapsado, ocultar la placa (tu sidebar tiene .collapsed)
    + '#sidebar.collapsed .avisa-brand-plate{display:none;}';
  var st = document.createElement('style');
  st.id = 'avisaStyles';
  st.textContent = css;
  document.head.appendChild(st);
}


// Cabecera AVISA en la parte superior de los modales/pop-ups
function _inyectarCabeceraModal() {
  try {
    var inner = document.getElementById('modalDetalleInner');
    if (!inner) return;
    // Evitar duplicar
    if (inner.querySelector('.avisa-modal-hd')) return;
    var cab = document.createElement('div');
    cab.className = 'avisa-modal-hd';
    cab.style.cssText = 'display:flex;align-items:center;gap:12px;padding:12px 16px;border-bottom:1px solid #e5e7eb;background:linear-gradient(90deg,#f5f8fd,#ffffff);border-radius:14px 14px 0 0';
    var logoSrc = (typeof LOGO_AVISA_COMPACTA !== 'undefined' && LOGO_AVISA_COMPACTA) ? LOGO_AVISA_COMPACTA : ((typeof LOGO_AVISA !== 'undefined') ? LOGO_AVISA : '');
    var imgHtml = logoSrc ? '<img src="'+logoSrc+'" alt="AVISA" style="height:34px;width:auto;flex-shrink:0">' : '';
    cab.innerHTML = imgHtml +
      '<div style="line-height:1.25">' +
        '<div style="font-weight:800;color:#0F2B48;font-size:13px;letter-spacing:.3px">AVISA</div>' +
        '<div style="font-size:10px;color:#5B6677">Aplicativo de Vigilancia y Seguimiento de Alertas de la OAIPCS del Sector Producci\u00F3n</div>' +
      '</div>';
    // Insertar como primer hijo del modal
    if (inner.firstChild) inner.insertBefore(cab, inner.firstChild);
    else inner.appendChild(cab);
  } catch(e) {}
}
function _observarModales() {
  try {
    var modal = document.getElementById('modalDetalle');
    if (!modal || modal._avisaObs) return;
    modal._avisaObs = true;
    var obs = new MutationObserver(function(){
      // Cuando el modal esta visible (sin 'hidden') y tiene contenido, inyectar cabecera
      if (!modal.classList.contains('hidden')) {
        _inyectarCabeceraModal();
      }
    });
    obs.observe(document.getElementById('modalDetalleInner') || modal, { childList:true, subtree:false });
    obs.observe(modal, { attributes:true, attributeFilter:['class'] });
  } catch(e) {}
}

function _marcaAVISA() {
  try {
    _inyectarEstilosAVISA();
    // 1) Reemplazar textos SIPRECS/SIPREC por AVISA en todo el DOM
    var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT, null, false);
    var nodos = [], n;
    while ((n = walker.nextNode())) { if (n.nodeValue && n.nodeValue.indexOf('SIPREC') >= 0) nodos.push(n); }
    for (var i = 0; i < nodos.length; i++) {
      nodos[i].nodeValue = nodos[i].nodeValue.replace(/SIPRECS/g, 'AVISA').replace(/SIPREC/g, 'AVISA');
    }
    // 2) Corregir atributos title/placeholder/value/alt
    var els = document.querySelectorAll('[title],[placeholder],[value],[alt]');
    for (var j = 0; j < els.length; j++) {
      ['title','placeholder','value','alt'].forEach(function(at){
        var v = els[j].getAttribute(at);
        if (v && v.indexOf('SIPREC') >= 0) els[j].setAttribute(at, v.replace(/SIPRECS/g,'AVISA').replace(/SIPREC/g,'AVISA'));
      });
    }
    // 3) Titulo de la pagina
    if (document.title && document.title.indexOf('SIPREC') >= 0) {
      document.title = document.title.replace(/SIPRECS/g,'AVISA').replace(/SIPREC/g,'AVISA');
    }
    // 4) Redisenar tarjeta de login
    var ls = document.getElementById('loginScreen');
    if (ls) {
      var caja = ls.querySelector('.login-card') || ls.querySelector('.login-box') || ls.querySelector('.card') || ls.firstElementChild || ls;
      // (tu .login-card ya tiene estilo propio; solo realzamos inputs via CSS)
      // Colocar el logo: si ya existe el <img> (puesto en el Index), asignar src;
      // si no existe, crearlo e insertarlo.
      var logoImg = document.getElementById('avisaLogoLogin');
      if (logoImg) {
        if (!logoImg.getAttribute('src')) logoImg.src = LOGO_AVISA;
      } else if (caja) {
        logoImg = document.createElement('img');
        logoImg.id = 'avisaLogoLogin';
        logoImg.src = LOGO_AVISA;
        logoImg.alt = 'AVISA';
        logoImg.style.cssText = 'display:block;margin:0 auto 10px;max-width:210px;width:75%;height:auto';
        var box = caja.querySelector('.login-logo') || caja;
        if (box.firstChild) box.insertBefore(logoImg, box.firstChild); else box.appendChild(logoImg);
      }
      // Ocultar cualquier <h1>/<h2> que diga AVISA o SIPREC (redundante con el logo)
      var titulos = caja ? caja.querySelectorAll('h1,h2') : [];
      for (var t = 0; t < titulos.length; t++) {
        var txt = (titulos[t].textContent||'').trim().toUpperCase();
        if (txt === 'AVISA' || txt === 'SIPREC' || txt === 'SIPRECS') { titulos[t].style.display = 'none'; }
      }
    }
  } catch (e) { }
}

function _marcaAVISAHeader() {
  try {
    if (document.getElementById('avisaBrandPlate')) return;
    var hd = document.querySelector('.sb-brand') || document.querySelector('#sidebar') || document.querySelector('.sidebar') || document.querySelector('aside');
    if (!hd) return;
    var plate = document.createElement('div');
    plate.id = 'avisaBrandPlate';
    plate.className = 'avisa-brand-plate';
    var img = document.createElement('img');
    img.src = LOGO_AVISA_COMPACTA;
    img.alt = 'AVISA';
    plate.appendChild(img);
    if (hd.firstChild) hd.insertBefore(plate, hd.firstChild); else hd.appendChild(plate);
  } catch (e) { }
}
