// Normaliza cualquier URL/ID de Google Drive a una URL renderizable en <img>
function _filtrarTablaSimple(tablaId, texto) {
  var tbl = document.getElementById(tablaId);
  if (!tbl) return;
  var q = String(texto||'').toLowerCase().trim();
  var filas = tbl.querySelectorAll('tbody tr');
  for (var i=0;i<filas.length;i++){
    var txt = (filas[i].innerText||filas[i].textContent||'').toLowerCase();
    filas[i].style.display = (!q || txt.indexOf(q)>=0) ? '' : 'none';
  }
}

function _driveImg(u){
  if(!u) return '';
  u=String(u).trim();
  if(!u) return '';
  // Extraer el ID de Drive de cualquier formato conocido
  var id='';
  // 1. ID suelto (sin http ni slash)
  if(u.indexOf('http')!==0 && u.indexOf('/')<0 && u.length>=20){ id=u; }
  // 2. formato /d/ID
  if(!id){ var p1=u.indexOf('/d/'); if(p1>=0){ var s1=u.substring(p1+3); var e1=s1.indexOf('/'); id=(e1>=0)?s1.substring(0,e1):s1; } }
  // 3. formato ?id=ID o &id=ID
  if(!id){ var p2=u.indexOf('id='); if(p2>=0){ var s2=u.substring(p2+3); var e2=s2.search(/[&?]/); id=(e2>=0)?s2.substring(0,e2):s2; } }
  // 4. formato lh3.googleusercontent.com/d/ID ya extraido arriba
  if(id){ return 'https://lh3.googleusercontent.com/d/'+id; }
  // Si ya es una URL http directa de imagen, devolverla tal cual
  if(u.indexOf('http')===0){ return u; }
  return u;
}

