function tip(msg, required) {
  var color = required ? '#c0392b' : '#0057a8';
  return '<span class="tip-ico" tabindex="0" style="color:' + color + '">' + "\u2753<span class=\"tip-box\">" + msg + '</span></span>';
}

// Genera label con asterisco para campos obligatorios
function lbl(texto, msg, req) {
  return '<label class="lbl-tip">' + texto + (req ? ' <span style="color:#c0392b">*</span>' : '') + (msg ? tip(msg, req) : '') + '</label>';
}

