// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// LOGIN \u2014 conecta con Apps Script
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function doLogin() {
  var dni = document.getElementById('lDNI').value.trim();
  var clave = document.getElementById('lClave').value.trim();
  if (!dni || !clave) {
    mostrarError('Por favor ingrese su DNI y clave');
    return;
  }
  if (dni.length < 8) {
    mostrarError("El DNI debe tener 8 d\u00EDgitos");
    return;
  }

  // Mostrar loader
  document.getElementById('btnLogin').disabled = true;
  document.getElementById('lload').style.display = 'block';
  document.getElementById('lerr').style.display = 'none';

  // Llamar a Apps Script
  google.script.run.withSuccessHandler(function (resultado) {
    document.getElementById('btnLogin').disabled = false;
    document.getElementById('lload').style.display = 'none';
    if (resultado && resultado.ok) {
      // Guardar sesi\u00F3n
      SESSION = {
        dni: dni,
        nombre: resultado.nombre,
        rol: resultado.rol,
        id: resultado.id,
        area: resultado.area || '',
        email: resultado.email || '',
        cargo: resultado.cargo || ''
      };
      iniciarApp();
    } else {
      mostrarError(resultado.msg || 'DNI o clave incorrectos');
      document.getElementById('lDNI').classList.add('err');
      document.getElementById('lClave').classList.add('err');
    }
  }).withFailureHandler(function (err) {
    document.getElementById('btnLogin').disabled = false;
    document.getElementById('lload').style.display = 'none';
    mostrarError("Error de conexi\u00F3n. Intente nuevamente.");
    console.error('Error login:', err);
  }).verificarLogin(dni, clave);
}

// Enter para login \u2014 con null-check para evitar crash en eval()
(function () {
  var cla = document.getElementById('lClave');
  var dni = document.getElementById('lDNI');
  if (cla) cla.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') doLogin();
  });
  if (dni) dni.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' && cla) cla.focus();
  });
})();
function limpiarErr() {
  document.getElementById('lerr').style.display = 'none';
  document.getElementById('lDNI').classList.remove('err');
  document.getElementById('lClave').classList.remove('err');
}
function mostrarError(msg) {
  document.getElementById('lerr').textContent = "\u274C " + msg;
  document.getElementById('lerr').style.display = 'block';
}
function doLogout() {
  SESSION = {
    dni: '',
    nombre: '',
    rol: '',
    id: '',
    area: '',
    email: '',
    cargo: ''
  };
  CACHE = {
    casos: null,
    alertas: null,
    rr: null,
    clima: null,
    hechos: null,
    acciones: null,
    actores: null,
    sectoristas: null,
    pf: null,
    autoridades: null,
    tipoCaso: null,
    tematica: null,
    sectores: null,
    intervencion: null,
    riesgos: null,
    departamentos: null,
    provincias: null,
    pasosAlerta: null,
    pasosCaso: null
  };
  document.getElementById('loginScreen').style.display = 'flex';
  document.getElementById('app').style.display = 'none';
  _marcaAVISA();
  document.getElementById('lDNI').value = '';
  document.getElementById('lClave').value = '';
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// INICIAR APP despu\u00E9s del login exitoso
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function iniciarApp() {
  // Ocultar login, mostrar app
  document.getElementById('loginScreen').style.display = 'none';
  document.getElementById('app').style.display = 'block';
  _marcaAVISA(); _marcaAVISAHeader();

  // Actualizar header
  var ini = SESSION.nombre.split(' ').map(function (w) {
    return w[0];
  }).slice(0, 2).join('').toUpperCase();
  document.getElementById('hAv').textContent = ini;
  document.getElementById('hName').textContent = SESSION.nombre.split(' ').slice(0, 2).join(' ');
  document.getElementById('hRole').textContent = SESSION.rol;
  document.getElementById('hDate').textContent = new Date().toLocaleDateString('es-PE', {
    day: '2-digit',
    month: 'short',
    year: 'numeric'
  });
  document.getElementById('dashBienvenida').textContent = 'Bienvenido/a, ' + SESSION.nombre.split(' ')[0] + " \u2014 " + SESSION.cargo;

  // Control de visibilidad por rol
  aplicarPermisosPorRol();
  mostrarBienvenida(SESSION.nombre.split(' ')[0]);

  // Si es PF o Autoridad ir directo a Pendientes
  // Navegar siempre al Dashboard al inicio
  goM('dashboard', document.querySelector('[onclick*=dashboard]') || null);
  {
    // Pre-cargar pendientes en background para badge
    google.script.run.withSuccessHandler(function (res) {
      try {
        var nb = document.getElementById('nbPendientes');
        if (nb && res && res.ok && res.data) nb.textContent = res.data.length;
      } catch (e) {}
    }).withFailureHandler(function () {}).getPendientes(SESSION.id || '', SESSION.rol || '');
  }
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// PERMISOS POR ROL
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function aplicarPermisosPorRol() {
  var rol = SESSION.rol;

  // \u2500\u2500 Mostrar/ocultar sidebar seg\u00FAn rol \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
  // PuntoFocal y Autoridad tienen vista limitada
  if (rol === 'PuntoFocal') {
    // Ocultar TODO el sidebar menos Pendientes
    document.querySelectorAll('.nav').forEach(function (n) {
      var txt = n.textContent.trim();
      if (!txt.includes('Pendientes')) n.style.display = 'none';
    });
    document.querySelectorAll('.sb-sec').forEach(function (s) {
      return s.style.display = 'none';
    });
  }
  if (rol === 'Autoridad') {
    // Solo Dashboard principal y Pendientes
    document.querySelectorAll('.nav').forEach(function (n) {
      var txt = n.textContent.trim();
      if (!txt.includes('Dashboard') && !txt.includes('Pendientes')) {
        n.style.display = 'none';
      }
    });
    document.querySelectorAll('.sb-sec').forEach(function (s) {
      return s.style.display = 'none';
    });
  }

  // Admin \u2014 ver todo incluyendo Maestros y Log
  if (rol === 'Admin') {
    document.querySelectorAll('.role-admin-only').forEach(function (el) {
      return el.style.display = 'flex';
    });
    document.getElementById('sbAdminSec').style.display = 'block';
  }

  // Directora \u2014 ver Log de Env\u00EDos + PF + Autoridades
  if (rol === 'Directora') {
    var sbLog = document.getElementById('sbLog');
    if (sbLog) sbLog.style.display = 'flex';
    var sbNavPF1 = document.getElementById('sbNavPF');
    if (sbNavPF1) sbNavPF1.style.display = 'flex';
    var sbNavAut1 = document.getElementById('sbNavAut');
    if (sbNavAut1) sbNavAut1.style.display = 'flex';
  }

  // Sectorista \u2014 ver PF y Autoridades (solo consulta)
  if (rol === 'Sectorista') {
    var sbNavPF2 = document.getElementById('sbNavPF');
    if (sbNavPF2) sbNavPF2.style.display = 'flex';
    var sbNavAut2 = document.getElementById('sbNavAut');
    if (sbNavAut2) sbNavAut2.style.display = 'flex';
  }
}

// \u2500\u2500 Verificar si un rol puede descargar \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
// Descarga PDF y Excel tienen el mismo permiso
function puedeDescargar() {
  return ['Admin', 'Sectorista', 'Directora'].includes(SESSION.rol);
}

// \u2500\u2500 Verificar si puede crear documentos \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function puedeCrear() {
  return ['Admin', 'Sectorista', 'Directora'].includes(SESSION.rol);
}

// \u2500\u2500 Verificar si puede validar un tipo \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function puedeValidar(tipo) {
  var rol = SESSION.rol;
  if (rol === 'Admin') return true;
  if (tipo === 'caso' || tipo === 'alerta') return rol === 'Directora' || rol === 'PuntoFocal';
  if (tipo === 'accion') return rol === 'Directora' || rol === 'PuntoFocal';
  if (tipo === 'reporte' || tipo === 'clima') return rol === 'Directora';
  return false;
}

// \u2500\u2500 Ocultar botones seg\u00FAn permiso \u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500
function aplicarPermisoBotones(contenedor) {
  if (!contenedor) return;
  // Botones de descarga PDF y Excel
  if (!puedeDescargar()) {
    contenedor.querySelectorAll('.bpdf, .bxl').forEach(function (b) {
      return b.style.display = 'none';
    });
  }
  // Botones de crear
  if (!puedeCrear()) {
    contenedor.querySelectorAll('.btn-crear').forEach(function (b) {
      return b.style.display = 'none';
    });
  }
}

