// NAVEGACI\u00D3N
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function goM(id, el) {
  document.querySelectorAll('.mod').forEach(function (m) {
    return m.classList.remove('on');
  });
  var mod = document.getElementById('mod-' + id);
  if (mod) mod.classList.add('on');
  document.querySelectorAll('.nav').forEach(function (n) {
    return n.classList.remove('on');
  });
  if (el) el.classList.add('on');
  if (window.innerWidth <= 768) document.getElementById('sidebar').classList.remove('open');
  switch (id) {
    case 'dashboard':
      cargarDashboard();
      break;
    case 'pendientes':
      cargarPendientes();
      break;
    case 'casos':
      cargarCasos();
      break;
    case 'hechos':
      cargarHechos();
      break;
    case 'acciones':
      cargarAcciones();
      break;
    case 'hitos':
      cargarHitos();
      break;
    case 'analisis':
      cargarAnalisis();
      break;
    case 'analisisregional':
      cargarAnalisisRegional();
      break;
    case 'organizaciones':
      _abrirModuloOrganizaciones();
      break;
    case 'locales':
      _abrirModuloLocales();
      break;
    case 'actores':
      cargarActores();
      break;
    case 'alertas':
      cargarAlertas();
      break;
    case 'rr':
      cargarRR();
      break;
    case 'clima':
      cargarClima();
      break;
    case 'redradar':
      cargarRedRadar();
      break;
    case 'reportes':
      cargarReportes();
      break;
    case 'rep-proceso':
      cargarReportes('proceso');
      break;
    case 'rep-ejecutivo':
      cargarReportes('ejecutivo');
      break;
    case 'rep-casos':
      _abrirReporteCasos();
      break;
    case 'rep-intervencion':
      cargarReportes('proceso');
      break;
    case 'rep-demandas':
      cargarReportes('proceso');
      break;
    case 'rep-actores':
      _abrirReporteActoresPDF();
      break;
    case 'rep-contacto':
      _abrirRepContacto();
      break;
    case 'rep-orgs':
      _abrirRepOrganizaciones();
      break;
    case 'rep-locales':
      _abrirRepLocales();
      break;
    case 'sectoristas':
      cargarSectoristas();
      break;
    case 'pf':
      cargarPF();
      break;
    case 'log':
      cargarLog();
      break;
    case 'autoridades':
      cargarAutoridades();
      break;
    case 'actoresestado':
      cargarActoresEstado();
      break;
    case 'demandas':
      cargarDemandas();
      break;
    case 'maestros':
      cargarMaestros();
      break;
  }
}
var sbOpen = true;
function irAModulo(id) {
  goM(id, document.querySelector('.nav') || null);
}
function toggleSB() {
  var sb = document.getElementById('sidebar');
  var ma = document.getElementById('mainArea');
  if (window.innerWidth <= 768) {
    sb.classList.toggle('open');
    return;
  }
  sbOpen = !sbOpen;
  if (sbOpen) {
    sb.style.transform = '';
    ma.style.marginLeft = 'var(--sb)';
  } else {
    sb.style.transform = 'translateX(-260px)';
    ma.style.marginLeft = '0';
  }
}
function sTab(prefix, id, btn) {
  // Cuando se abre el tab "nuevo", asegurar selects
  if (id === 'nuevo' || id === 'nueva') {
    setTimeout(function() {
      if (prefix === 'actores') {
        _asegurarDeptos('fa_ubigeo', ''); _asegurarAreas('fa_area', '');
      } else if (prefix === 'actoresEstado') {
        _asegurarDeptos('fae_ubigeo', ''); _asegurarAreas('fae_area', '');
      } else if (prefix === 'alertas') {
        // Asegurar que el selector de recurso pesquero est\u00E9 poblado
        var selRec = document.getElementById('na_recurso_add');
        if (selRec) {
          var hasOpts = false, oi;
          for (oi = 0; oi < selRec.options.length; oi++) { if (selRec.options[oi].value) { hasOpts = true; break; } }
          if (!hasOpts) llenarSelectConCacheRecurso('na_recurso_add');
        }
      }
    }, 50);
  }
  var mod = document.getElementById('mod-' + prefix) || document.getElementById(prefix + 'Content');
  if (mod) {
    mod.querySelectorAll('.tpane').forEach(function (t) {
      return t.classList.remove('on');
    });
    var p = document.getElementById(prefix + '-' + id);
    if (p) p.classList.add('on');
  }
  if (btn) {
    btn.closest('.tabs').querySelectorAll('.tb').forEach(function (b) {
      return b.classList.remove('on');
    });
    btn.classList.add('on');
  }
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// HELPERS
