function rBadge(r) {
  if (!r) return "<span class=\"badge b-gry\">\u2014</span>";
  if (r.includes("Cr\u00EDtico")) return "<span class=\"badge b-red\">\uD83D\uDD34 Cr\u00EDtico</span>";
  if (r.includes('Inminente')) return "<span class=\"badge b-amb\">\uD83D\uDFE0 Inminente</span>";
  if (r.includes('Intermedio')) return "<span class=\"badge b-amb\">\uD83D\uDFE1 Intermedio</span>";
  return "<span class=\"badge b-grn\">\uD83D\uDFE2 Bajo</span>";
}
