  document.getElementById('modalDetalleInner').innerHTML = html;
  document.getElementById('modalDetalle').classList.remove('hidden');
  var preSel = document.getElementById('mail_pre_sel');
  var mailBtn = document.getElementById('btn_mail_enviar');
