    var n = i + 1;
    var cls = n < pasoActual ? 'done' : n === pasoActual ? 'active' : '';
    var lbl = n < pasoActual ? 'done' : n === pasoActual ? 'active' : '';
    return "<div class=\"pstep ".concat(cls, "\">\n      <div class=\"ps-c ").concat(cls, "\">").concat(n < pasoActual ? "\u2713" : n, "</div>\n      <div class=\"ps-l ").concat(lbl, "\">").concat(p.Nombre_caso || p.Paso_caso, "<br>\n        <small style=\"opacity:.7;font-size:8px\">").concat(p.Estado_caso || '', "</small></div>\n    </div>");
