function mostrarBienvenida(usuario) {
  var key = 'sipok_' + SESSION.dni;
  try {
    if (localStorage.getItem(key)) return;
  } catch (e) {}
  var ov = document.createElement('div');
  ov.id = 'wov';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,30,70,.8);z-index:10000;display:flex;align-items:center;justify-content:center;padding:20px;backdrop-filter:blur(4px)';
  var h = '<div style="background:#fff;border-radius:16px;max-width:560px;width:100%;box-shadow:0 24px 60px rgba(0,0,0,.3);overflow:hidden">';
  h += "<div style=\"background:linear-gradient(135deg,#002d5a,#0057a8);padding:24px 28px;color:#fff\"><div style=\"font-size:28px\">\uD83D\uDEE1\uFE0F</div>";
  h += '<h2 style="font-size:18px;font-weight:700;margin:8px 0 0">Bienvenido/a al Sistema AVISA</h2>';
  h += "<p style=\"font-size:13px;opacity:.8;margin:4px 0 0\">Ministerio de Producci\u00F3n &mdash; OAIPCS</p></div>";
  h += '<div style="padding:24px 28px">';
  h += '<p style="font-size:14px;color:#1a2332;margin-bottom:14px">Hola <strong>' + usuario + '</strong>, bienvenido/a al AVISA.</p>';
  h += '<div style="background:#f0f7ff;border-radius:10px;padding:14px;margin-bottom:12px;border-left:4px solid #0057a8">';
  h += "<p style=\"font-size:12.5px;font-weight:600;color:#002d5a;margin-bottom:4px\">\uD83D\uDCCB Sistema AVISA</p>";
  h += "<p style=\"font-size:12px;color:#3d4f66;line-height:1.6\">Plataforma institucional para el seguimiento y prevenci\u00F3n de conflictos sociales en Pesca, Acuicultura, MYPE e Industria.</p></div>";
  h += '<div style="background:#fef9ee;border-radius:10px;padding:14px;margin-bottom:16px;border-left:4px solid #b45309">';
  h += "<p style=\"font-size:12.5px;font-weight:600;color:#92400e;margin-bottom:4px\">\u26A0\uFE0F Confidencialidad (Ley N\u00B0 29733)</p>";
  h += "<p style=\"font-size:12px;color:#3d4f66;line-height:1.6\">Informaci\u00F3n <strong>CONFIDENCIAL</strong>. Uso exclusivo institucional.</p></div>";
  h += '<label style="display:flex;align-items:flex-start;gap:10px;cursor:pointer;margin-bottom:14px">';
  h += '<input type="checkbox" id="chkAc" style="width:18px;height:18px;margin-top:2px;accent-color:#0057a8;flex-shrink:0">';
  h += "<span style=\"font-size:13px;color:#1a2332;line-height:1.5\">Acepto los t\u00E9rminos de confidencialidad y me comprometo a usar la informaci\u00F3n solo para fines institucionales.</span></label>";
  h += "<button id=\"btnAc\" onclick=\"cerrarBienvenida()\" disabled style=\"width:100%;padding:12px;background:#c8d3e6;color:#fff;border:none;border-radius:8px;font-size:14px;font-weight:600;cursor:not-allowed;font-family:inherit;transition:all .2s\">Ingresar al sistema \u2192</button>";
  h += '</div></div>';
  ov.innerHTML = h;
  document.body.appendChild(ov);
  setTimeout(function () {
    var chk = document.getElementById('chkAc'),
      btn = document.getElementById('btnAc');
    if (chk && btn) chk.addEventListener('change', function () {
      btn.disabled = !chk.checked;
      btn.style.background = chk.checked ? '#0057a8' : '#c8d3e6';
      btn.style.cursor = chk.checked ? 'pointer' : 'not-allowed';
    });
  }, 100);
}
function cerrarBienvenida() {
  try {
    localStorage.setItem('sipok_' + SESSION.dni, '1');
  } catch (e) {}
  var ov = document.getElementById('wov');
  if (ov) {
    ov.style.opacity = '0';
    ov.style.transition = 'opacity .3s';
    setTimeout(function () {
      ov.remove();
    }, 300);
  }
}
function cargarDistritos(selId, provId) {
  var sel = document.getElementById(selId);
  if (!sel || !provId) return;
  sel.innerHTML = '<option value="">-- Distrito --</option>';
  if (CACHE.distritos && CACHE.distritos.length) {
    CACHE.distritos.filter(function (d) {
      return String(d.ID_Provincia || '') === String(provId);
    }).forEach(function (d) {
      var o = document.createElement('option');
      o.value = d.ID_Distrito || '';
      o.textContent = d.Distrito || d.Nombre_Distrito || '';
      sel.appendChild(o);
    });
  } else {
    google.script.run.withSuccessHandler(function (r) {
      if (r && r.ok) {
        CACHE.distritos = r.data;
        cargarDistritos(selId, provId);
      }
    }).withFailureHandler(function () {}).getDistritos();
  }
}
