function xTab(btn, contentId, paneId) {
  var div = document.getElementById(contentId);
  if (!div) return;
  div.querySelectorAll('.tpane').forEach(function (t) {
    t.classList.remove('on');
  });
  var p = document.getElementById(paneId);
  if (p) p.classList.add('on');
  if (btn && btn.closest) {
    var tabs = btn.closest('.tabs');
    if (tabs) tabs.querySelectorAll('.tb').forEach(function (b) {
      b.classList.remove('on');
    });
    btn.classList.add('on');
  }
}
function xTabReset(contentId, paneId, tabsSelector) {
  var div = document.getElementById(contentId);
  if (!div) return;
  div.querySelectorAll('.tpane').forEach(function (t) {
    t.classList.remove('on');
  });
  var p = document.getElementById(paneId);
  if (p) p.classList.add('on');
  var tabs = div.querySelector(tabsSelector);
  if (tabs) {
    tabs.querySelectorAll('.tb').forEach(function (b) {
      b.classList.remove('on');
    });
    var first = tabs.querySelector('.tb');
    if (first) first.classList.add('on');
  }
}
