// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// L\u00CDNEA DE TIEMPO DEL CASO
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function verLineaTiempo(codigoCaso) {
  console.log('[LT-DEBUG v3] verLineaTiempo INICIADA para', codigoCaso);
  try {
    var modal = document.getElementById('modalDetalleInner');
    modal.innerHTML = "<div class=\"modal-hd\"><div><h2>\uD83D\uDCC5 L\u00EDnea de Tiempo</h2>" + '<div style="font-size:12px;color:var(--g500)">Caso: ' + codigoCaso + '</div></div>' + "<button class=\"mclose\" onclick=\"cerrarModal()\">\u2715</button></div>" + '<div class="modal-bd" id="avisaLTContenido2026">' + '<div class="spinner-wrap"><div class="spinner"></div><p>Cargando hechos... (v3)</p></div>' + '</div>' + '<div class="modal-ft"><button class="btn bs" onclick="cerrarModal()">Cerrar</button></div>';
    document.getElementById('modalDetalle').classList.remove('hidden');
    console.log('[LT-DEBUG v3] Modal abierto correctamente, a punto de llamar a getHechosCaso');
  } catch(eModal) {
    console.log('[LT-DEBUG v3] ERROR al abrir el modal:', eModal);
    toast('Error al abrir el modal: ' + String(eModal), 'err');
    return;
  }

  var _ltRespondio = false;
  setTimeout(function(){
    if (_ltRespondio) return;
    console.log('[LT-DEBUG v3] TIMEOUT de 12s alcanzado sin respuesta');
    var div = document.getElementById('avisaLTContenido2026');
    if (div) div.innerHTML = '<div style="text-align:center;padding:30px;color:#c0392b">El servidor no respondi\u00F3 a tiempo (m\u00E1s de 12 segundos).<br>Puede que el backend desplegado no sea la versi\u00F3n mas reciente.<br>Verifica en Apps Script: Implementar &gt; Administrar implementaciones &gt; Editar &gt; Nueva versi\u00F3n.</div>';
  }, 12000);

  try {
    google.script.run.withSuccessHandler(function (r) {
      console.log('[LT-DEBUG v4] SuccessHandler ejecutado. r=', JSON.stringify(r).slice(0,300));
      console.log('[LT-DEBUG v4] _backendVersion recibido:', (r && r._backendVersion) || 'NO PRESENTE (backend viejo sin actualizar)');
      console.log('[LT-DEBUG v4] _diag recibido:', (r && r._diag) || 'NO PRESENTE');
      _ltRespondio = true;
      try {
        if (!r || !r.ok) {
          var divErr = document.getElementById('avisaLTContenido2026');
          if (divErr) divErr.innerHTML = '<div style="text-align:center;padding:30px;color:#c0392b">El servidor respondio con error: ' + esc2((r && r.msg) || 'desconocido') + '</div>';
          return;
        }
        var crudos = r.data || [];
        console.log('[LT-DEBUG v3] Hechos crudos recibidos:', crudos.length);
        var hechos = crudos.map(function(h){
          return {
            ID_Hecho: h.ID_Hecho || '',
            Fecha: h.Fecha,
            Tipo_Hecho: h.Tipo_Hecho || h.Tipo || '',
            Hecho_Critico: h.Hecho_Critico || h.Critico || '',
            Descripcion: h.Descripcion || h.Descripcion_Hecho || ''
          };
        });
        console.log('[LT-DEBUG v3] Llamando a renderLineaTiempo con', hechos.length, 'hechos mapeados');
        renderLineaTiempo(hechos, codigoCaso);
        console.log('[LT-DEBUG v3] renderLineaTiempo termino sin error');
      } catch(eRender) {
        console.log('[LT-DEBUG v3] ERROR dentro del successHandler:', eRender);
        var div = document.getElementById('avisaLTContenido2026');
        if (div) div.innerHTML = '<div style="text-align:center;padding:30px;color:#c0392b">Error al mostrar la linea de tiempo: ' + esc2(String(eRender)) + '</div>';
      }
    }).withFailureHandler(function (e) {
      console.log('[LT-DEBUG v3] FailureHandler ejecutado:', e);
      _ltRespondio = true;
      var div = document.getElementById('avisaLTContenido2026');
      if (div) div.innerHTML = '<div style="text-align:center;padding:30px;color:#c0392b">Error al cargar hechos: ' + esc2(String(e)) + '</div>';
    }).getHechosCaso(String(codigoCaso));
    console.log('[LT-DEBUG v3] Llamada a getHechosCaso enviada (esperando respuesta async)');
  } catch(eCall) {
    console.log('[LT-DEBUG v3] ERROR al INICIAR la llamada google.script.run:', eCall);
  }
}

function _categoriaHecho(h) {
  var tipo = String(h.Tipo_Hecho||'').toLowerCase();
  var crit = String(h['Hecho_Cr\u00EDtico']||h.Hecho_Critico||'')==='Si';
  if (crit || tipo.indexOf('protesta')>=0 || tipo.indexOf('bloqueo')>=0) {
    return { color:'#E24B4A', img: (typeof IMG_LT_PROTESTAS!=='undefined'?IMG_LT_PROTESTAS:''), nombre:'Protesta o Bloqueo / Cr\u00EDtico' };
  }
  if (tipo.indexOf('reuni\u00F3n')>=0 || tipo.indexOf('reunion')>=0 || tipo.indexOf('di\u00E1logo')>=0 || tipo.indexOf('dialogo')>=0) {
    return { color:'#1D9E75', img: (typeof IMG_LT_REUNIONES!=='undefined'?IMG_LT_REUNIONES:''), nombre:'Reuni\u00F3n T\u00E9cnica / Espacio de Di\u00E1logo' };
  }
  if (tipo.indexOf('comunicado')>=0 || tipo.indexOf('documento')>=0 || tipo.indexOf('normatividad')>=0) {
    return { color:'#2B5797', img: (typeof IMG_LT_DOCUMENTOS!=='undefined'?IMG_LT_DOCUMENTOS:''), nombre:'Comunicado / Normatividad' };
  }
  return { color:'#2B5797', img: (typeof IMG_LT_TUERCA!=='undefined'?IMG_LT_TUERCA:''), nombre:'Otro' };
}
function renderLineaTiempo(hechos, codigoCaso) {
  var div = document.getElementById('avisaLTContenido2026');
  console.log('[LT-DEBUG v4] renderLineaTiempo: elemento avisaLTContenido2026 encontrado?', !!div);
  if (!div) { console.log('[LT-DEBUG v4] ABORTANDO: no se encontro el elemento #avisaLTContenido2026 en el DOM'); return; }
  window._lineaTiempoCaso = codigoCaso;
  if (!hechos.length) {
    window._lineaTiempoHechos = [];
    div.innerHTML = '<div style="text-align:center;padding:30px;color:var(--g500)">Sin hechos registrados para este caso (v4)</div>';
    console.log('[LT-DEBUG v4] innerHTML actualizado a "Sin hechos". innerHTML actual del div (primeros 80 chars):', div.innerHTML.slice(0,80));
    return;
  }
  var ordenados = hechos.slice().sort(function (a, b) {
    return (_parsearFechaSegura(a.Fecha || a.Fecha_Hecho)||0) - (_parsearFechaSegura(b.Fecha || b.Fecha_Hecho)||0);
  });
  // Guardar el orden final CON el identificador que realmente se usa en cada checkbox,
  // para que _ltDescargarPDF pueda encontrar exactamente los mismos hechos seleccionados.
  window._lineaTiempoHechos = ordenados.map(function(h, idx){
    var hidCalc = h.ID_Hecho || ('idx'+idx);
    var copia = {};
    for (var k in h) copia[k] = h[k];
    copia._hid = hidCalc;
    return copia;
  });
  var cards = ordenados.map(function (h, idx) {
    var cat = _categoriaHecho(h);
    var color = cat.color;
    var hid = h.ID_Hecho || ('idx'+idx);
    var imgHtml = cat.img ? '<img src="'+cat.img+'" style="width:36px;height:36px;object-fit:contain;display:block;margin:0 auto 4px">' : '';
    var conector = idx > 0 ? (
      '<div style="flex:0 0 54px;position:relative;display:flex;align-items:center;justify-content:center;padding-top:34px">' +
        '<div style="position:absolute;top:19px;left:0;right:0;text-align:center;font-size:9px;color:var(--g500)">&#8594;</div>' +
        '<div style="background:#fff;border:1px solid var(--g300);border-radius:10px;padding:2px 6px;font-size:9.5px;color:var(--g600);white-space:nowrap;position:relative;z-index:1;margin-top:8px">' + esc2(fmtFecha(h.Fecha || h.Fecha_Hecho)) + '</div>' +
      '</div>'
    ) : '';
    return conector + '<div style="flex:0 0 220px;position:relative;padding-top:34px">' +
      '<label style="position:absolute;top:-6px;right:8px;z-index:3;background:#fff;border-radius:4px;padding:1px"><input type="checkbox" class="lt-check" value="'+esc2(hid)+'" style="width:16px;height:16px;cursor:pointer"></label>' +
      '<div style="position:absolute;top:11px;left:50%;transform:translateX(-50%);width:16px;height:16px;border-radius:50%;background:' + color + ';border:3px solid #fff;box-shadow:0 0 0 2px ' + color + ';z-index:2"></div>' +
      '<div style="background:#fff;border-radius:10px;border-top:4px solid ' + color + ';box-shadow:0 2px 8px rgba(0,0,0,.08);padding:10px 12px;margin:0 8px">' +
        imgHtml +
        '<div style="font-size:11px;color:var(--g500);font-weight:600;margin-bottom:4px;text-align:center">' + fmtFecha(h.Fecha || h.Fecha_Hecho) + '</div>' +
        '<div style="font-weight:700;font-size:12px;color:' + color + ';margin-bottom:4px;text-align:center">' + esc2(h.Tipo_Hecho || 'Hecho') + '</div>' +
        '<div style="font-size:11px;color:var(--g700);line-height:1.4">' + esc2(String(h.Descripcion || h.Descripcion_Hecho || '').slice(0,120)) + '</div>' +
      '</div>' +
    '</div>';
  }).join('');
  console.log('[LT-DEBUG v5] Tarjetas construidas, cantidad:', ordenados.length, '| longitud del HTML de tarjetas:', cards.length);
  var htmlFinal = '<div style="display:flex;justify-content:flex-end;gap:8px;margin-bottom:10px">'
    + '<button class="btn bs btn-sm" onclick="_ltSeleccionarTodos()">Seleccionar todos</button>'
    + '<button class="btn bp btn-sm" onclick="_ltDescargarPDF()">&#x1F4C4; Descargar / Imprimir PDF</button>'
    + '</div>'
    + '<div style="position:relative;overflow-x:auto;padding:8px 0 16px"><div style="position:absolute;top:19px;left:0;right:0;height:3px;background:var(--g200);z-index:0"></div><div style="display:flex;position:relative;z-index:1;min-width:min-content">' + cards + '</div></div>';
  console.log('[LT-DEBUG v5] HTML final construido, longitud total:', htmlFinal.length);
  div.innerHTML = htmlFinal;
  console.log('[LT-DEBUG v5] div.innerHTML ASIGNADO. Verificacion inmediata - longitud actual de div.innerHTML:', div.innerHTML.length, '| primeros 100 chars:', div.innerHTML.slice(0,100));
  console.log('[LT-DEBUG v5] Verificando que el elemento siga en el DOM real:', document.getElementById('avisaLTContenido2026') === div);
  var modalCheck = document.getElementById('modalDetalle');
  console.log('[LT-DEBUG v5] Modal contenedor - classList actual:', modalCheck ? modalCheck.className : 'NO ENCONTRADO', '| tiene clase hidden?', modalCheck ? modalCheck.classList.contains('hidden') : 'N/A');
}
function _ltSeleccionarTodos() {
  var boxes = document.querySelectorAll('.lt-check');
  var todosMarcados = Array.prototype.every.call(boxes, function(b){ return b.checked; });
  boxes.forEach(function(b){ b.checked = !todosMarcados; });
}
function _ltDescargarPDF() {
  var boxes = document.querySelectorAll('.lt-check');
  var seleccionados = [];
  boxes.forEach(function(b){ if (b.checked) seleccionados.push(b.value); });
  // window._lineaTiempoHechos ya viene ORDENADO por fecha y con el mismo _hid que usa cada checkbox
  var hechos = window._lineaTiempoHechos || [];
  var ordenados = seleccionados.length ? hechos.filter(function(h){ return seleccionados.indexOf(h._hid||'') >= 0; }) : hechos;
  if (!ordenados.length) { toast('No hay hechos para exportar', 'err'); return; }
  var filas = ordenados.map(function(h){
    var cat = _categoriaHecho(h);
    var imgHtml = cat.img ? '<img src="'+cat.img+'" style="width:28px;height:28px;object-fit:contain">' : '';
    return '<div class="lt-pdf-card" style="border-top:4px solid '+cat.color+'">'
      + '<div style="text-align:center">'+imgHtml+'</div>'
      + '<div class="lt-pdf-fecha">'+fmtFecha(h.Fecha||h.Fecha_Hecho)+'</div>'
      + '<div class="lt-pdf-tipo" style="color:'+cat.color+'">'+esc2(h.Tipo_Hecho||'Hecho')+'</div>'
      + '<div class="lt-pdf-desc">'+esc2(String(h.Descripcion||h.Descripcion_Hecho||''))+'</div>'
      + '</div>';
  }).join('');
  var nombreCaso = window._lineaTiempoCaso || '';
  var win = window.open('', '_blank');
  win.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>Linea de Tiempo - '+esc2(nombreCaso)+'</title><style>'
    + '@page { size: A4 landscape; margin: 12mm; }'
    + 'body{font-family:Arial,sans-serif;margin:0;padding:16px;color:#222}'
    + 'h1{font-size:18px;margin:0 0 4px}'
    + '.sub{font-size:12px;color:#666;margin-bottom:16px}'
    + '.lt-pdf-grid{display:flex;flex-wrap:wrap;gap:12px}'
    + '.lt-pdf-card{width:150px;background:#fff;border-radius:8px;box-shadow:0 1px 4px rgba(0,0,0,.15);padding:8px;break-inside:avoid;page-break-inside:avoid}'
    + '.lt-pdf-fecha{font-size:10px;color:#666;font-weight:600;text-align:center;margin-top:4px}'
    + '.lt-pdf-tipo{font-size:11px;font-weight:700;text-align:center;margin:2px 0}'
    + '.lt-pdf-desc{font-size:10px;line-height:1.35;color:#333}'
    + '</style></head><body>'
    + '<h1>L\u00EDnea de Tiempo del Caso</h1>'
    + '<div class="sub">'+esc2(nombreCaso)+' &nbsp;\u2014&nbsp; Generado: '+fmtFecha(new Date().toISOString().slice(0,10))+'</div>'
    + '<div class="lt-pdf-grid">'+filas+'</div>'
    + '</body></html>');
  win.document.close();
  setTimeout(function(){ win.print(); }, 400);
}

function renderAccionesHitos(acciones, codigoCaso) {
  var div = document.getElementById('accionesHitosContent');
  if (!div) return;
  if (!acciones.length) {
    div.innerHTML = '<div style="text-align:center;padding:30px;color:var(--g500)">Sin acciones registradas para este caso</div>';
    return;
  }
  var rows = acciones.map(function (a) {
    return '<tr>' + '<td><code>' + (a.ID_Accion || '') + '</code></td>' + '<td style="font-size:12px">' + (a.Tipo_Accion || '') + '</td>' + '<td style="font-size:12px">' + (a.Descripcion_Accion || '') + '</td>' + '<td>' + sBadge(a.Estado_Hito || a.Estado || '') + '</td>' + '<td style="font-size:12px">' + fmtFecha(a.Fecha_Compromiso || a.Fecha) + '</td>' + '</tr>';
  }).join('');
  div.innerHTML = '<div class="tw"><table><thead><tr>' + "<th>ID</th><th>Tipo</th><th>Descripci\u00F3n</th><th>Estado</th><th>Fecha</th>" + '</tr></thead><tbody>' + rows + '</tbody></table></div>';
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// BRIDGE: Departamentos, Actores, Recursos vinculados al caso
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function agregarDepto() {
  var sel = document.getElementById('nc_depto_add');
  var chk = document.getElementById('nc_depto_principal');
  var id = sel.value;
  var txt = sel.options[sel.selectedIndex] ? sel.options[sel.selectedIndex].text : '';
  if (!id) {
    toast('Seleccione un departamento', 'err');
    return;
  }
  if (!window._bridgeDeptos) window._bridgeDeptos = [];
  if (window._bridgeDeptos.find(function (d) {
    return d.ID_Ubigeo === id;
  })) {
    toast('Departamento ya agregado', 'err');
    return;
  }
  var esPrincipal = chk && chk.checked;
  window._bridgeDeptos.push({
    ID_Ubigeo: id,
    Departamento: txt,
    Es_Principal: esPrincipal ? "S\u00ED" : 'No'
  });
  renderBridgeLista('nc_deptos_lista', window._bridgeDeptos, 'ID_Ubigeo', 'Departamento', 'Es_Principal', eliminarDepto);
  sel.value = '';
  if (chk) chk.checked = false;
}
function eliminarDepto(id) {
  window._bridgeDeptos = (window._bridgeDeptos || []).filter(function (d) {
    return d.ID_Ubigeo !== id;
  });
  renderBridgeLista('nc_deptos_lista', window._bridgeDeptos, 'ID_Ubigeo', 'Departamento', 'Es_Principal', eliminarDepto);
}
function agregarRecurso() {
  var sel = document.getElementById('nc_recurso_add');
  if (!sel) { toast('Selector de recurso no disponible', 'err'); return; }
  var id = sel.value;
  var txt = sel.options[sel.selectedIndex] ? sel.options[sel.selectedIndex].text : '';
  if (!id) {
    var realOpts = 0, oi;
    for (oi = 0; oi < sel.options.length; oi++) { if (sel.options[oi].value) realOpts++; }
    if (realOpts === 0) {
      llenarSelectConCacheRecurso('nc_recurso_add');
      toast('Cargando recursos pesqueros, intente de nuevo en un momento', 'info');
    } else {
      toast('Seleccione un recurso', 'err');
    }
    return;
  }
  if (!window._bridgeRecursos) window._bridgeRecursos = [];
  if (window._bridgeRecursos.find(function (r) {
    return r.ID_Recurso === id;
  })) {
    toast('Recurso ya agregado', 'err');
    return;
  }
  window._bridgeRecursos.push({
    ID_Recurso: id,
    Nombre: txt
  });
  renderBridgeLista('nc_recursos_lista', window._bridgeRecursos, 'ID_Recurso', 'Nombre', null, eliminarRecurso);
  sel.value = '';
}
function eliminarRecurso(id) {
  window._bridgeRecursos = (window._bridgeRecursos || []).filter(function (r) {
    return r.ID_Recurso !== id;
  });
  renderBridgeLista('nc_recursos_lista', window._bridgeRecursos, 'ID_Recurso', 'Nombre', null, eliminarRecurso);
}
function renderBridgeLista(containerId, items, keyField, labelField, extraField, removeFn) {
  var div = document.getElementById(containerId);
  if (!div) return;
  if (!items || !items.length) {
    div.innerHTML = '<span style="font-size:12px;color:var(--g500)">Sin elementos agregados</span>';
    return;
  }
  // Usar DOM en lugar de innerHTML para evitar problemas de comillas
  div.innerHTML = '';
  items.forEach(function (item) {
    var label = item[labelField] || item[keyField] || '';
    var extra = extraField && item[extraField] ? ' (' + item[extraField] + ')' : '';
    var id = item[keyField];
    var span = document.createElement('span');
    span.style.cssText = 'display:inline-flex;align-items:center;gap:4px;background:var(--blue-pale);color:var(--blue);padding:4px 10px;border-radius:20px;font-size:12px;font-weight:500;margin:2px';
    span.textContent = label + extra;
    var btn = document.createElement('button');
    btn.textContent = "\u00D7";
    btn.style.cssText = 'background:none;border:none;color:var(--blue);cursor:pointer;font-size:14px;padding:0 0 0 4px;line-height:1';
    btn.setAttribute('data-id', id);
    btn.onclick = function () {
      removeFn(this.getAttribute('data-id'));
    };
    span.appendChild(btn);
    div.appendChild(span);
  });
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// FUNCIONES GEN\u00C9RICAS PARA BRIDGES (Alerta, RR, Clima)
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
var _bridgeGen = {};
function iniciarBridgesGen(prefix) {
  _bridgeGen[prefix] = {
    deptos: [],
    actores: [],
    actoresE: [],
    recursos: []
  };
  ['deptos', 'actores', 'actoresE', 'recursos'].forEach(function (k) {
    var el = document.getElementById(prefix + '_' + k + '_lista');
    if (el) el.innerHTML = '';
  });
  // Llenar selects
  llenarSelectConCache(prefix + '_depto_add', 'departamentos', 'ID_Ubigeo', 'Departamento', 'getDepartamentos');
  llenarSelectConCacheRecurso(prefix + '_recurso_add');
  // Llenar selector de Actor Social con formato "Nombre - Organizacion"
  (function(){
    var selA = document.getElementById(prefix + '_actor_add');
    if (!selA) return;
    var llenarA = function(data){
      selA.innerHTML = '<option value="">-- Seleccionar Actor Social --</option>';
      (data||[]).filter(function(a){ return (a.ID_Tipo_Actor||'') !== 'Actor del Estado'; }).forEach(function(a){
        var o=document.createElement('option');
        o.value=a.ID_Actor||'';
        var org=a.Organizacion||a.Organizacion||'';
        o.setAttribute('data-nombre', a.Nombre_Actor||'');
        o.setAttribute('data-org', org);
        o.textContent=(a.Nombre_Actor||'') + (org?' - '+org:'');
        selA.appendChild(o);
      });
    };
    if (CACHE.actores && CACHE.actores.length) { llenarA(CACHE.actores); }
    else { google.script.run.withSuccessHandler(function(r){ if(r&&r.ok){ CACHE.actores=r.data; llenarA(r.data); } }).withFailureHandler(function(){}).getActoresSociales(); }
  })();
  // Llenar selector de Actor del Estado si existe en este formulario
  (function(){
    var selE = document.getElementById(prefix + '_actorE_add');
    if (!selE) return;
    var llenarE = function(data){
      selE.innerHTML = '<option value="">-- Seleccionar Actor del Estado --</option>';
      (data||[]).forEach(function(a){
        var o=document.createElement('option');
        o.value=a.ID_Actor_Estado||a.ID_Actor||'';
        // Area/Sector/Oficina: ID_Entidad (ej. "Produce"), o ID_Area, o Cargo como respaldo
        var area=a.ID_Entidad||a.ID_Area||a.ID_Unidad||a.Cargo||'';
        o.setAttribute('data-nombre', a.Nombre_Actor||'');
        o.setAttribute('data-area', area);
        o.textContent=(a.Nombre_Actor||'')+(area?' - '+area:'');
        selE.appendChild(o);
      });
    };
    if (CACHE.actoresEstado && CACHE.actoresEstado.length) { llenarE(CACHE.actoresEstado); }
    else { google.script.run.withSuccessHandler(function(r){ if(r&&r.ok){ CACHE.actoresEstado=r.data; llenarE(r.data); } }).withFailureHandler(function(){}).getActoresEstado(); }
  })();
}
function llenarSelectConCache(selId, cacheKey, valKey, lblKey, fn) {
  if (CACHE[cacheKey] && CACHE[cacheKey].length) {
    llenarSelect(selId, CACHE[cacheKey], valKey, lblKey);
  } else {
    var ok = function (r) {
      if (r && r.ok) {
        CACHE[cacheKey] = r.data;
        llenarSelect(selId, r.data, valKey, lblKey);
      }
    };
    var run = google.script.run.withSuccessHandler(ok).withFailureHandler(function () {});
    if (fn === 'getDepartamentos') run.getDepartamentos();
    else if (fn === 'getActores') run.getActores();
    else if (fn === 'getActoresSociales') run.getActoresSociales();
    else if (fn === 'getActoresEstado') run.getActoresEstado();
    else if (fn === 'getSectores') run.getSectores();
    else if (fn === 'getSectoristas') run.getSectoristas();
    else if (fn === 'getTematica') run.getTematica();
    else if (fn === 'getRiesgos') run.getRiesgos();
    else if (fn === 'getNivelesAlerta') run.getNivelesAlerta();
    else if (fn === 'getRecursos') run.getRecursos();
    else if (fn === 'getProvincias') run.getProvincias();
    else if (fn === 'getDistritos') run.getDistritos();
    else if (fn === 'getTipoCaso') run.getTipoCaso();
    else if (fn === 'getIntervencion') run.getIntervencion();
  }
}
function detectarColRecursoID(data) {
  if (!data || !data.length) return 'ID_Recurso';
  var keys = Object.keys(data[0]);
  // 1. Columna expl\u00EDcita ID_Recurso
  if (data[0]['ID_Recurso'] !== undefined && String(data[0]['ID_Recurso']).trim() !== '') return 'ID_Recurso';
  // 2. Columna sin encabezado (clave '') cuyo valor parece RECU-###
  if (data[0][''] !== undefined && /^RECU/i.test(String(data[0]['']).trim())) return '';
  // 3. Cualquier clave cuyo primer valor matchee RECU-###
  for (var i = 0; i < keys.length; i++) {
    var v = String(data[0][keys[i]] || '').trim();
    if (/^RECU[-_]?[0-9]+$/i.test(v)) return keys[i];
  }
  // 4. Clave que contenga 'id' y 'recurso'
  var idKey = keys.find(function (k) { var kn = k.toLowerCase().replace(/[^a-z]/g, ''); return kn.indexOf('id') >= 0 && kn.indexOf('recurso') >= 0; });
  return idKey || 'ID_Recurso';
}
function llenarSelectConCacheRecurso(selId) {
  if (CACHE.recursos && CACHE.recursos.length) {
    var colR = detectarColRecurso(CACHE.recursos);
    var colID = detectarColRecursoID(CACHE.recursos);
    llenarSelect(selId, CACHE.recursos, colID, colR);
  } else {
    google.script.run.withSuccessHandler(function (r) {
      if (r && r.ok) {
        CACHE.recursos = r.data;
        var colR = detectarColRecurso(r.data);
        var colID = detectarColRecursoID(r.data);
        llenarSelect(selId, r.data, colID, colR);
      }
    }).withFailureHandler(function () {}).getRecursos();
  }
}
function detectarColRecurso(data) {
  if (!data || !data.length) return 'Nombre_comun_Recurso';
  var keys = Object.keys(data[0]);
  // 1. Buscar columna normalizada sin tilde
  if (data[0]['Nombre_comun_Recurso'] !== undefined) return 'Nombre_comun_Recurso';
  // 2. Buscar columna con tilde (Nombre_com\u00FAn_Recurso)
  var found = keys.find(function (k) {
    return k === "Nombre_com\u00FAn_Recurso";
  });
  if (found) return found;
  // 3. Buscar cualquier columna que contenga 'nombre' y ('comun' o 'recurso' o 'com')
  found = keys.find(function (k) {
    var kl = k.toLowerCase().replace(/[\u00E0-\u00FF]/g, function (c) {
      return {
        "\u00E1": 'a',
        "\u00E9": 'e',
        "\u00ED": 'i',
        "\u00F3": 'o',
        "\u00FA": 'u',
        "\u00FC": 'u'
      }[c] || c;
    }).replace(/[^a-z_]/g, '');
    return kl.indexOf('nombre') >= 0 && (kl.indexOf('comun') >= 0 || kl.indexOf('recurso') >= 0);
  });
  return found || keys.find(function (k) {
    return k.toLowerCase().indexOf('nombre') >= 0;
  }) || 'Nombre_comun_Recurso';
}
function agregarDeptoGen(prefix) {
  var sel = document.getElementById(prefix + '_depto_add');
  var chk = document.getElementById(prefix + '_depto_principal');
  var id = sel ? sel.value : '';
  var txt = sel && sel.selectedIndex >= 0 ? sel.options[sel.selectedIndex].text : '';
  if (!id) {
    toast('Seleccione un departamento', 'err');
    return;
  }
  if (!_bridgeGen[prefix]) _bridgeGen[prefix] = {
    deptos: [],
    actores: [],
    recursos: []
  };
  if (_bridgeGen[prefix].deptos.find(function (d) {
    return d.ID_Ubigeo === id;
  })) {
    toast('Departamento ya agregado', 'err');
    return;
  }
  var esPrincipal = chk && chk.checked;
  _bridgeGen[prefix].deptos.push({
    ID_Ubigeo: id,
    Departamento: txt,
    Es_Principal: esPrincipal ? "S\u00ED" : 'No'
  });
  renderBridgeLista(prefix + '_deptos_lista', _bridgeGen[prefix].deptos, 'ID_Ubigeo', 'Departamento', 'Es_Principal', function (pid) {
    _bridgeGen[prefix].deptos = _bridgeGen[prefix].deptos.filter(function (d) {
      return d.ID_Ubigeo !== pid;
    });
    renderBridgeLista(prefix + '_deptos_lista', _bridgeGen[prefix].deptos, 'ID_Ubigeo', 'Departamento', 'Es_Principal', arguments.callee);
  });
  if (sel) sel.value = '';
  if (chk) chk.checked = false;
}
function _filtrarSelectBuscable(inputEl, selectId) {
  var sel = document.getElementById(selectId);
  if (!sel) return;
  var q = (inputEl.value||'').toLowerCase().trim();
  for (var i=0; i<sel.options.length; i++) {
    var opt = sel.options[i];
    if (!opt.value) { opt.hidden = false; continue; } // mantener placeholder visible
    var texto = (opt.textContent||'').toLowerCase();
    opt.hidden = q ? (texto.indexOf(q) < 0) : false;
  }
  // Si el valor seleccionado quedo oculto, resetear
  if (sel.selectedIndex >= 0 && sel.options[sel.selectedIndex].hidden) sel.selectedIndex = 0;
}
function _crearActorRapidoYAgregar(prefix) {
  var nombre = prompt('Nombre completo del nuevo Actor Social:');
  if (!nombre || !nombre.trim()) return;
  nombre = nombre.trim();
  toast('\u23F3 Creando actor...');
  google.script.run.withSuccessHandler(function(r){
    if (r && r.ok) {
      toast('\u2705 Actor creado: ' + r.nombre + ' (complete sus datos luego en el m\u00F3dulo Actores)');
      if (!CACHE.actores) CACHE.actores = [];
      CACHE.actores.push({ ID_Actor: r.id, Nombre_Actor: r.nombre, Activo: 'S\u00ED' });
      if (prefix === 'ea') {
        var idAlerta = window._editAlertaId;
        google.script.run.withSuccessHandler(function(r2){
          if (r2 && r2.ok) { editarAlerta(idAlerta); }
        }).withFailureHandler(function(){}).agregarActorAAlerta(idAlerta, r.id);
        return;
      }
      var sel = document.getElementById(prefix + '_actor_add');
      if (sel) {
        var opt = document.createElement('option');
        opt.value = r.id;
        opt.text = r.nombre;
        opt.setAttribute('data-nombre', r.nombre);
        opt.setAttribute('data-org', '');
        sel.appendChild(opt);
        sel.value = r.id;
        agregarActorGen(prefix);
      }
    } else toast(r && r.msg || 'Error', 'err');
  }).withFailureHandler(function(e){ toast('Error: '+String(e), 'err'); }).crearActorRapido(nombre);
}
function agregarActorGen(prefix) {
  var sel = document.getElementById(prefix + '_actor_add');
  var id = sel ? sel.value : '';
  if (!id) {
    toast('Seleccione un actor social', 'err');
    return;
  }
  var opt = sel.options[sel.selectedIndex];
  // Formato: "Nombre - Organizacion"
  var nombre = opt.getAttribute('data-nombre') || '';
  var org = opt.getAttribute('data-org') || '';
  var etiqueta = nombre + (org ? ' - ' + org : '');
  if (!etiqueta) etiqueta = opt.text;
  if (!_bridgeGen[prefix]) _bridgeGen[prefix] = {
    deptos: [],
    actores: [],
    actoresE: [],
    recursos: []
  };
  if (_bridgeGen[prefix].actores.find(function (a) {
    return a.ID_Actor === id;
  })) {
    toast('Actor ya agregado', 'err');
    return;
  }
  _bridgeGen[prefix].actores.push({
    ID_Actor: id,
    Nombre: etiqueta
  });
  renderBridgeLista(prefix + '_actores_lista', _bridgeGen[prefix].actores, 'ID_Actor', 'Nombre', null, function (pid) {
    _bridgeGen[prefix].actores = _bridgeGen[prefix].actores.filter(function (a) {
      return a.ID_Actor !== pid;
    });
    renderBridgeLista(prefix + '_actores_lista', _bridgeGen[prefix].actores, 'ID_Actor', 'Nombre', null, arguments.callee);
  });
  if (sel) sel.value = '';
}
function agregarRecursoGen(prefix) {
  var sel = document.getElementById(prefix + '_recurso_add');
  if (!sel) { toast('Selector de recurso no disponible', 'err'); return; }
  var id = sel.value;
  var txt = sel.selectedIndex >= 0 ? sel.options[sel.selectedIndex].text : '';
  if (!id) {
    // Si el selector no tiene opciones cargadas, intentar recargar y avisar
    var realOpts = 0, oi;
    for (oi = 0; oi < sel.options.length; oi++) { if (sel.options[oi].value) realOpts++; }
    if (realOpts === 0) {
      llenarSelectConCacheRecurso(prefix + '_recurso_add');
      toast('Cargando recursos pesqueros, intente de nuevo en un momento', 'info');
    } else {
      toast('Seleccione un recurso', 'err');
    }
    return;
  }
  if (!_bridgeGen[prefix]) _bridgeGen[prefix] = {
    deptos: [],
    actores: [],
    recursos: []
  };
  if (_bridgeGen[prefix].recursos.find(function (r) {
    return r.ID_Recurso === id;
  })) {
    toast('Recurso ya agregado', 'err');
    return;
  }
  _bridgeGen[prefix].recursos.push({
    ID_Recurso: id,
    Nombre: txt
  });
  renderBridgeLista(prefix + '_recursos_lista', _bridgeGen[prefix].recursos, 'ID_Recurso', 'Nombre', null, function (pid) {
    _bridgeGen[prefix].recursos = _bridgeGen[prefix].recursos.filter(function (r) {
      return r.ID_Recurso !== pid;
    });
    renderBridgeLista(prefix + '_recursos_lista', _bridgeGen[prefix].recursos, 'ID_Recurso', 'Nombre', null, arguments.callee);
  });
  if (sel) sel.value = '';
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// VER PROCESO / RECORRIDO DEL CASO O REPORTE
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function nuevaLineaTiempo(codigoCaso, nombreCaso) {
  verLineaTiempo(codigoCaso);
}

function verRecorridoCaso(codigoCaso, nombreCaso) {
  var modal = document.getElementById('modalDetalleInner');
  modal.innerHTML = '<div class="modal-hd">' + "<div><h2>\u23F1\uFE0F L\u00EDnea de Tiempo [v4]</h2>" + '<div style="font-size:12px;color:var(--g500)">' + codigoCaso + " \u2014 " + (nombreCaso || '') + '</div></div>' + "<button class=\"mclose\" onclick=\"cerrarModal()\">\u2715</button>" + '</div>' + '<div class="modal-bd" id="recorridoContent" style="padding:16px;max-height:70vh;overflow-y:auto">' + "<div class=\"spinner-wrap\"><div class=\"spinner\"></div><p>Cargando l\u00EDnea de tiempo...</p></div>" + '</div>' + '<div class="modal-ft"><button class="btn bs" onclick="cerrarModal()">Cerrar</button></div>';
  document.getElementById('modalDetalle').classList.remove('hidden');

  var _suf = String(codigoCaso||'').replace(/\D/g,'').replace(/^0+/,'');
  function _m(v){ v=String(v||''); if(v===codigoCaso) return true; var s=v.replace(/\D/g,'').replace(/^0+/,''); return _suf && s===_suf; }

  function pintar(hechos) {
    var div = document.getElementById('recorridoContent');
    if (!div) return;
    try {
    var filtrados = (hechos||[]).filter(function(h){ return _m(h.ID_Caso) || _m(h.Codigo_Caso); });
    if (!filtrados.length) {
      div.innerHTML = '<p style="color:var(--g500);text-align:center;padding:30px">No hay hechos registrados para este caso.</p>';
      return;
    }
    filtrados.sort(function(a,b){ return (_parsearFechaSegura(a.Fecha)||0) - (_parsearFechaSegura(b.Fecha)||0); });
    var cards = filtrados.map(function(h){
      var crit = String(h['Hecho_Cr\u00EDtico']||h.Hecho_Critico||'')==='Si';
      var color = crit ? '#E24B4A' : '#E67E22';
      return '<div style="flex:0 0 220px;position:relative;padding-top:34px">' +
        '<div style="position:absolute;top:11px;left:50%;transform:translateX(-50%);width:16px;height:16px;border-radius:50%;background:' + color + ';border:3px solid #fff;box-shadow:0 0 0 2px ' + color + ';z-index:2"></div>' +
        '<div style="background:#fff;border-radius:10px;border-top:4px solid ' + color + ';box-shadow:0 2px 8px rgba(0,0,0,.08);padding:10px 12px;margin:0 8px">' +
          '<div style="font-size:11px;color:var(--g500);font-weight:600;margin-bottom:4px">' + fmtFecha(h.Fecha) + '</div>' +
          '<div style="font-weight:700;font-size:12px;color:' + color + ';margin-bottom:4px">' + (crit?"\uD83D\uDD34 ":"\uD83D\uDCCB ") + esc2(h.Tipo_Hecho||'Hecho') + '</div>' +
          '<div style="font-size:11px;color:var(--g700);line-height:1.4">' + esc2(String(h.Descripcion||'').slice(0,140)) + '</div>' +
        '</div>' +
      '</div>';
    }).join('');
    div.innerHTML = '<div style="position:relative;overflow-x:auto;padding:8px 0 16px"><div style="position:absolute;top:19px;left:0;right:0;height:3px;background:var(--g200);z-index:0"></div><div style="display:flex;position:relative;z-index:1;min-width:min-content">' + cards + '</div></div>';
    } catch(errP) {
      div.innerHTML = '<p style="color:#c0392b;text-align:center;padding:30px">ERROR al pintar: ' + String(errP && errP.message ? errP.message : errP) + '</p>';
    }
  }

  // Usar cache si existe, sino cargar de FACT_Hechos_Casos
  var _done = false;
  function _pintarUnaVez(hechos) {
    if (_done) return;
    _done = true;
    pintar(hechos);
  }
  // Timeout de seguridad: si el backend no responde en 8s, avisar
  setTimeout(function(){
    if (!_done) {
      var div = document.getElementById('recorridoContent');
      if (div) div.innerHTML = '<p style="color:#c0392b;text-align:center;padding:30px">TIMEOUT: getHechos no respondi\u00F3 en 3s. El backend Codigo_nuevo.gs probablemente no est\u00E1 desplegado.</p>';
      _done = true;
    }
  }, 3000);

  if (CACHE.hechos && CACHE.hechos.length) {
    _pintarUnaVez(CACHE.hechos);
  } else {
    google.script.run.withSuccessHandler(function (r) {
      CACHE.hechos = (r && r.ok && r.data) ? r.data : [];
      _pintarUnaVez(CACHE.hechos);
    }).withFailureHandler(function (e) {
      var div = document.getElementById('recorridoContent');
      if (div && !_done) { div.innerHTML = '<p style="color:#c0392b;text-align:center;padding:30px">Error al cargar hechos: ' + esc2(String(e)) + '</p>'; _done = true; }
    }).getHechos();
  }
}

function _renderRecorridoHorizontal(codigoCaso, data) {
  var div = document.getElementById('recorridoContent');
  if (!div) return;
  var _suf = String(codigoCaso||'').replace(/\\D/g,'').replace(/^0+/,'');
  function _m(v){ v=String(v||''); if(v===codigoCaso) return true; var s=v.replace(/\\D/g,'').replace(/^0+/,''); return _suf && s===_suf; }
  var eventos = [];
  (data.proceso || []).forEach(function (p) {
    var paso = Number(p.Paso_caso || 0);
    var nombres = { 1: "\uD83D\uDCDD Elaboraci\u00F3n", 2: "\uD83D\uDCE4 Remisi\u00F3n", 3: "\u2714\uFE0F Cierre", 4: "\uD83D\uDD04 Reapertura" };
    eventos.push({ fecha: p.Fecha_inicio || '', color: paso===1?'#7F77DD':paso===2?'#2980B9':paso===3?'#1D9E75':'#EF9F27', icono: "\uD83D\uDCCC", titulo: nombres[paso]||('Paso '+paso), desc: p.Observaciones||'' });
  });
  (data.hechos || []).forEach(function (h) {
    if (!(_m(h.ID_Caso) || _m(h.Codigo_Caso))) return;
    var crit = String(h['Hecho_Cr\u00EDtico']||h.Hecho_Critico||'')==='Si';
    eventos.push({ fecha: h.Fecha||'', color: crit?'#E24B4A':'#E67E22', icono: crit?"\uD83D\uDD34":"\uD83D\uDCCB", titulo: (h.Tipo_Hecho||'Hecho'), desc: h.Descripcion||'' });
  });
  (data.alertas || []).forEach(function (a) {
    eventos.push({ fecha: a.Fecha||'', color: '#E24B4A', icono: "\uD83D\uDEA8", titulo: 'Alerta: '+(a.Titulo_Alerta||a.ID_Alerta||''), desc: a.Situacion_Actual||a["Situaci\u00F3n_Actual"]||'' });
  });
  eventos.sort(function (a, b) { return (_parsearFechaSegura(a.fecha)||0) - (_parsearFechaSegura(b.fecha)||0); });
  if (!eventos.length) {
    div.innerHTML = '<p style="color:var(--g500);text-align:center;padding:30px">No hay eventos registrados para este caso.</p>';
    return;
  }
  // Timeline HORIZONTAL: scroll horizontal con tarjetas y linea central
  var cards = eventos.map(function(ev){
    var fecha = fmtFecha(ev.fecha);
    return '<div style="flex:0 0 220px;position:relative;padding-top:34px">' +
      '<div style="position:absolute;top:11px;left:50%;transform:translateX(-50%);width:16px;height:16px;border-radius:50%;background:' + ev.color + ';border:3px solid #fff;box-shadow:0 0 0 2px ' + ev.color + ';z-index:2"></div>' +
      '<div style="background:#fff;border-radius:10px;border-top:4px solid ' + ev.color + ';box-shadow:0 2px 8px rgba(0,0,0,.08);padding:10px 12px;margin:0 8px">' +
        '<div style="font-size:11px;color:var(--g500);font-weight:600;margin-bottom:4px">' + fecha + '</div>' +
        '<div style="font-weight:700;font-size:12px;color:' + ev.color + ';margin-bottom:4px">' + ev.icono + ' ' + esc2(ev.titulo) + '</div>' +
        (ev.desc ? '<div style="font-size:11px;color:var(--g700);line-height:1.4">' + esc2(String(ev.desc).slice(0,120)) + '</div>' : '') +
      '</div>' +
    '</div>';
  }).join('');
  div.innerHTML = '<div style="position:relative;overflow-x:auto;padding:8px 0 16px"><div style="position:absolute;top:19px;left:0;right:0;height:3px;background:var(--g200);z-index:0"></div><div style="display:flex;position:relative;z-index:1;min-width:min-content">' + cards + '</div></div>';
}

function verRecorridoReporte(idReporte, tituloReporte) {
  var modal = document.getElementById('modalDetalleInner');
  modal.innerHTML = '<div class="modal-hd">' + "<div><h2>\uD83D\uDDD3\uFE0F Recorrido del reporte</h2>" + '<div style="font-size:12px;color:var(--g500)">' + (tituloReporte || idReporte) + '</div></div>' + "<button class=\"mclose\" onclick=\"cerrarModal()\">\u2715</button>" + '</div>' + '<div class="modal-bd" id="recorridoContent">' + '<div class="spinner-wrap"><div class="spinner"></div><p>Cargando proceso...</p></div>' + '</div>' + '<div class="modal-ft">' + '<button class="btn bs" onclick="cerrarModal()">Cerrar</button>' + '</div>';
  document.getElementById('modalDetalle').classList.remove('hidden');
  google.script.run.withSuccessHandler(function (r) {
    if (r && r.ok) renderRecorrido(r.data, 'reporte');else document.getElementById('recorridoContent').innerHTML = '<p style="color:var(--g500);text-align:center;padding:20px">Sin registros de proceso</p>';
  }).withFailureHandler(function () {
    document.getElementById('recorridoContent').innerHTML = '<p style="color:var(--red);text-align:center;padding:20px">Error al cargar</p>';
  }).getProcesoReporte(idReporte, '');
}
function renderRecorrido(pasos, tipo) {
  var div = document.getElementById('recorridoContent');
  if (!div) return;
  if (!pasos || !pasos.length) {
    div.innerHTML = '<p style="color:var(--g500);text-align:center;padding:20px">Sin pasos registrados</p>';
    return;
  }
  var nombresDefault = tipo === 'caso' ? ["Elaboraci\u00F3n", "Remisi\u00F3n", "Desestimaci\u00F3n", 'Cierre', 'Reapertura'] : ["Elaboraci\u00F3n", "Remisi\u00F3n", "Desestimaci\u00F3n", 'Cierre', 'Reapertura'];
  var html = '<div class="pflow">';
  pasos.forEach(function (p, i) {
    var paso = p.Paso_caso || p.Paso_Num || i + 1;
    var nombre = nombresDefault[paso - 1] || 'Paso ' + paso;
    var fechaFin = p.Fecha_Fin || p.Fecha_fin || '';
    var cerrado = !!fechaFin;
    var activo = !cerrado && i === pasos.length - 1;
    var cls = cerrado ? 'done' : activo ? 'active' : '';
    html += '<div class="pstep ' + cls + '">' + '<div class="ps-c ' + cls + '">' + paso + '</div>' + '<div class="ps-l ' + cls + '">' + nombre + (cerrado ? '<br>' + fmtFecha(fechaFin) : '') + (activo ? '<br>En curso' : '') + '</div>' + '</div>';
  });
  html += '</div>';

  // Tabla detalle
  html += '<div class="tw" style="margin-top:16px"><table>' + "<thead><tr><th>Paso</th><th>Responsable</th><th>Fecha inicio</th><th>Fecha fin</th><th>D\u00EDas</th><th>Observaciones</th></tr></thead><tbody>";
  pasos.forEach(function (p) {
    var paso = p.Paso_caso || p.Paso_Num || '';
    html += '<tr>' + '<td><span class="badge b-blu">Paso ' + paso + '</span></td>' + '<td style="font-size:12px">' + (p.ID_Responsable || "\u2014") + '</td>' + '<td style="font-size:12px">' + fmtFecha(p.Fecha_inicio || p.Fecha_Inicio || '') + '</td>' + '<td style="font-size:12px">' + fmtFecha(p.Fecha_Fin || p.Fecha_fin || '') + '</td>' + '<td style="font-size:12px">' + (p.Dias_Demora || 0) + 'd</td>' + '<td style="font-size:12px;max-width:200px">' + (p.Observaciones || "\u2014") + '</td>' + '</tr>';
  });
  html += '</tbody></table></div>';
  div.innerHTML = html;
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// AVANZAR PASO DESDE PENDIENTES (Directora valida/rechaza)
// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
function modalAvanzarPaso(tipo, id, titulo, pasoActual) {
  window._avanceTipo = tipo;
  window._avanceId = id;
  window._avancePaso = pasoActual;
  var modal = document.getElementById('modalDetalleInner');
  modal.innerHTML = '';
  var hd = document.createElement('div');
  hd.className = 'modal-hd';
  hd.innerHTML = "<div><h2>\u2705 Validar documento</h2><div style=\"font-size:12px;color:var(--g500)\">" + tipo + ': ' + titulo + '</div></div>';
  var btnX = document.createElement('button');
  btnX.className = 'mclose';
  btnX.textContent = "\u2715";
  btnX.onclick = function () {
    cerrarModal();
  };
  hd.appendChild(btnX);
  var bd = document.createElement('div');
  bd.className = 'modal-bd';
  bd.innerHTML = '<div class="f s3" style="margin-bottom:12px"><label>Observaciones</label>' + '<textarea id="obs_avance" rows="3" placeholder="Observaciones del paso..."></textarea></div>' + '<div class="f" style="margin-bottom:12px"><label>Motivo (si rechaza)</label>' + '<input type="text" id="motivo_avance" placeholder="Motivo de rechazo..."></div>';
  var ft = document.createElement('div');
  ft.className = 'modal-ft';
  var bA = document.createElement('button');
  bA.className = 'btn bgrn';
  bA.textContent = "\u2705 Aprobar";
  bA.onclick = function () {
    confirmarAvance(window._avanceTipo, window._avanceId, window._avancePaso, true);
  };
  var bD = document.createElement('button');
  bD.className = 'btn bred';
  bD.textContent = "\u21A9 Devolver";
  bD.onclick = function () {
    confirmarAvance(window._avanceTipo, window._avanceId, window._avancePaso, false);
  };
  var bC = document.createElement('button');
  bC.className = 'btn bs';
  bC.textContent = 'Cancelar';
  bC.onclick = function () {
    cerrarModal();
  };
  ft.appendChild(bA);
  ft.appendChild(bD);
  ft.appendChild(bC);
  modal.appendChild(hd);
  modal.appendChild(bd);
  modal.appendChild(ft);
  document.getElementById('modalDetalle').classList.remove('hidden');
}
function confirmarAvance(tipo, id, pasoActual, aprobar) {
  var obs = (document.getElementById('obs_avance') || {}).value || '';
  var motivo = (document.getElementById('motivo_avance') || {}).value || '';
  cerrarModal();
  toast("\u23F3 Procesando...");
  function onSuccess(r) {
    console.log('[AVISA] confirmarAvance respuesta:', JSON.stringify(r));
    if (r && r.ok) {
      toast(aprobar ? "\u2705 Aprobado \u2014 Paso " + (r.nuevoPaso || '?') : "\u21A9 Devuelto al sectorista");
      CACHE.casos = null;
      CACHE.alertas = null;
      CACHE.rr = null;
      CACHE.clima = null;
      cargarPendientes();
    } else {
      toast(r && r.msg || 'Error al procesar', 'err');
    }
  }
  function onError(e) {
    console.error('[AVISA] confirmarAvance error:', e);
    toast("Error de conexi\u00F3n: " + (e && e.message ? e.message : String(e)), 'err');
  }
  if (tipo === 'Caso') {
    google.script.run.withSuccessHandler(onSuccess).withFailureHandler(onError).avanzarPasoCaso(id, pasoActual, SESSION.id, obs, motivo);
  } else {
    google.script.run.withSuccessHandler(onSuccess).withFailureHandler(onError).avanzarPasoReporte(id, pasoActual, SESSION.id, obs);
  }
}

// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550
// VER FICHA DEL CASO \u2014 popup solo lectura
