function _repGenerico(cfg) {
  document.querySelectorAll('.mod').forEach(function(m){ m.classList.remove('on'); });
  var mod = _crearModDinamico(cfg.id);
  mod.classList.add('on');
  window._repCfg = cfg;
  // Construir barra de filtros
  var fbar = '';
  cfg.filtros.forEach(function(fl){
    if (fl.tipo==='depto') {
      fbar += '<select id="'+fl.id+'" style="font-size:12px" onchange="_repFiltrar()"><option value="">Todos los departamentos</option></select>';
    } else {
      fbar += '<input type="text" id="'+fl.id+'" placeholder="'+(fl.ph||'')+'" style="width:150px;font-size:12px" oninput="_repFiltrar()">';
    }
  });
  var ths = '<th style="width:40px;text-align:center"><input type="checkbox" id="repChkAll" onchange="_repToggleAll(this)"></th>';
  cfg.cols.forEach(function(c){ ths += '<th>'+c+'</th>'; });
  mod.innerHTML = '<div class="sc">'
    + '<div class="sc-head">'
      + '<h3>'+cfg.titulo+'</h3>'
    + '</div>'
    + '<p style="font-size:13px;color:#555;margin:4px 0 10px">Seleccione los elementos que desea incluir y presione Generar PDF o Word.</p>'
    + '<div class="fbar" style="flex-wrap:wrap;gap:6px;align-items:center">'+fbar
      + '<button class="btn bs btn-sm" onclick="_repToggleTodos()">Seleccionar todos</button>'
      + '<button class="btn btn-sm" style="background:#E24B4A;color:#fff" onclick="_repGenerar(\'pdf\')">\uD83D\uDCC4 Generar PDF (<span id="repSelCnt">0</span>)</button>'
      + '<button class="btn btn-sm" style="background:#2B5797;color:#fff" onclick="_repGenerar(\'word\')">\uD83D\uDCDD Generar Word</button>'
    + '</div>'
    + '<div class="tw"><table id="repTabla"><thead><tr>'+ths+'</tr></thead><tbody></tbody></table></div>'
    + '</div>';
  window._repSel = {};
  cfg.cargar(function(datos){
    window._repDatos = datos || [];
    _repLlenarDepto();
    _repFiltrar();
  });
}
function _repLlenarDepto() {
  var cfg = window._repCfg; if(!cfg) return;
  var flDepto = cfg.filtros.filter(function(f){return f.tipo==='depto';})[0];
  if (!flDepto) return;
  var sel = document.getElementById(flDepto.id);
  if (!sel) return;
  _getDeptosList(function(lista){
    sel.innerHTML = _optsDeptos(lista, true, '');
  });
}
function _repFiltrar() {
  var cfg = window._repCfg; if(!cfg) return;
  var f = {};
  cfg.filtros.forEach(function(fl){
    var el = document.getElementById(fl.id);
    f[fl.id] = el ? (fl.tipo==='depto'? el.value : (el.value||'').toLowerCase()) : '';
  });
  var lista = (window._repDatos||[]).filter(function(x){ return cfg.match(x, f); });
  window._repFiltrado = lista;
  var tb = document.querySelector('#repTabla tbody');
  if (!tb) return;
  var h = '';
  lista.forEach(function(x){
    var id = cfg.idOf(x);
    var checked = window._repSel[id] ? ' checked' : '';
    var celdas = cfg.fila(x).map(function(v){ return '<td style="font-size:12px">'+esc2(v)+'</td>'; }).join('');
    h += '<tr><td style="text-align:center"><input type="checkbox"'+checked+' onchange="_repToggle(\''+esc2(id)+'\',this)"></td>'+celdas+'</tr>';
  });
  tb.innerHTML = h || '<tr><td colspan="'+(cfg.cols.length+1)+'" style="text-align:center;padding:20px;color:#999">Sin resultados</td></tr>';
  _repActualizarCnt();
}
function _repToggle(id, chk) {
  if (chk.checked) window._repSel[id] = true;
  else delete window._repSel[id];
  _repActualizarCnt();
}
function _repToggleTodos() {
  var cfg = window._repCfg; if(!cfg) return;
  var lista = window._repFiltrado || [];
  // Si todos ya estan seleccionados, deseleccionar; si no, seleccionar todos
  var todosSel = lista.length>0 && lista.every(function(x){ return window._repSel[cfg.idOf(x)]; });
  lista.forEach(function(x){
    var id = cfg.idOf(x);
    if (todosSel) delete window._repSel[id];
    else window._repSel[id] = true;
  });
  _repFiltrar();
}
function _repToggleAll(chk) {
  var cfg = window._repCfg; if(!cfg) return;
  (window._repFiltrado||[]).forEach(function(x){
    var id = cfg.idOf(x);
    if (chk.checked) window._repSel[id] = true;
    else delete window._repSel[id];
  });
  _repFiltrar();
}
function _repActualizarCnt() {
  var n = Object.keys(window._repSel||{}).length;
  var el = document.getElementById('repSelCnt');
  if (el) el.textContent = n;
}
function _repGenerar(formato) {
  var cfg = window._repCfg; if(!cfg) return;
  var ids = Object.keys(window._repSel||{});
  if (!ids.length) { toast('Seleccione al menos un elemento','err'); return; }
  var metodo = cfg.generar(ids, formato);
  toast('\u23F3 Generando reporte ('+ids.length+')...');
  google.script.run.withSuccessHandler(function(r){
    if (r && r.ok && r.url) { window.open(r.url,'_blank'); toast('\u2705 Reporte generado'); }
    else toast(r && r.msg || 'Error al generar','err');
  }).withFailureHandler(function(e){ toast('Error: '+String(e),'err'); })[metodo](ids, formato);
}

function _abrirModuloContactoActores() {
  document.querySelectorAll('.mod').forEach(function(m){ m.classList.remove('on'); });
  var mod = _crearModDinamico('mod-repcontacto');
  mod.classList.add('on');
  mod.innerHTML = '<div class="sc">'
    + '<div class="sc-head">'
      + '<h3>\uD83D\uDCC7 Contacto de Actores \u2014 <span id="cntContacto">0</span></h3>'
      + '<div style="display:flex;gap:6px;flex-wrap:wrap">'
        + '<button class="btn btn-sm" style="background:#E24B4A;color:#fff" onclick="_reporteContacto(\'pdf\')">\uD83D\uDCC4 PDF</button>'
        + '<button class="btn btn-sm" style="background:#2B5797;color:#fff" onclick="_reporteContacto(\'word\')">\uD83D\uDCDD Word</button>'
      + '</div>'
    + '</div>'
    + '<p style="font-size:12px;color:#666;margin:4px 0 10px">Reporte de datos de contacto: Nombre, DNI, Tel\u00E9fono y Email. Filtra y genera.</p>'
    + '<div class="fbar" style="flex-wrap:wrap;gap:6px">'
      + '<input type="text" id="fContNombre" placeholder="Nombre..." style="width:150px;font-size:12px" oninput="_filtrarContacto()">'
      + '<select id="fContDepto" style="font-size:12px" onchange="_filtrarContacto()"><option value="">Todos los departamentos</option></select>'
      + '<input type="text" id="fContOrg" placeholder="Organizaci\u00F3n..." style="width:140px;font-size:12px" oninput="_filtrarContacto()">'
      + '<input type="text" id="fContCargo" placeholder="Cargo..." style="width:120px;font-size:12px" oninput="_filtrarContacto()">'
      + '<select id="fContPerfil" style="font-size:12px" onchange="_filtrarContacto()"><option value="">Todos los perfiles</option><option value="Perfil-01">Dialogante</option><option value="Perfil-02">Legitimante</option><option value="Perfil-03">Disruptivo</option></select>'
    + '</div>'
    + '<div class="tw"><table id="tblContacto"><thead><tr><th>Nombre</th><th>DNI</th><th>Tel\u00E9fono</th><th>Email</th><th>Organizaci\u00F3n</th><th>Depto.</th></tr></thead><tbody></tbody></table></div>'
    + '</div>';
  // Cargar actores
  if (CACHE.actores && CACHE.actores.length) {
    window._contactoLista = CACHE.actores;
    _llenarFiltroDeptoContacto();
    _filtrarContacto();
  } else {
    google.script.run.withSuccessHandler(function(r){
      if (r && r.ok) CACHE.actores = r.data;
      window._contactoLista = CACHE.actores || [];
      _llenarFiltroDeptoContacto();
      _filtrarContacto();
    }).withFailureHandler(function(e){ toast('Error cargando actores','err'); }).getActores();
  }
}
function _llenarFiltroDeptoContacto() {
  var sel = document.getElementById('fContDepto');
  if (!sel) return;
  _getDeptosList(function(lista){ sel.innerHTML = _optsDeptos(lista, true, ''); });
}
function _filtrarContacto() {
  var nombre = ((document.getElementById('fContNombre')||{}).value||'').toLowerCase();
  var depto = (document.getElementById('fContDepto')||{}).value||'';
  var org = ((document.getElementById('fContOrg')||{}).value||'').toLowerCase();
  var cargo = ((document.getElementById('fContCargo')||{}).value||'').toLowerCase();
  var perfil = (document.getElementById('fContPerfil')||{}).value||'';
  var lista = (window._contactoLista||[]).filter(function(a){
    if (nombre && (a.Nombre_Actor||'').toLowerCase().indexOf(nombre)<0) return false;
    if (depto && String(a.ID_Ubigeo||'')!==depto) return false;
    if (org && (a.Institucion||a.Organizacion||'').toLowerCase().indexOf(org)<0) return false;
    if (cargo && (a.Cargo||'').toLowerCase().indexOf(cargo)<0) return false;
    if (perfil && (a.ID_Perfil||a.Categoria||'')!==perfil) return false;
    return true;
  });
  window._contactoFiltrado = lista;
  var tb = document.querySelector('#tblContacto tbody');
  var cnt = document.getElementById('cntContacto');
  if (cnt) cnt.textContent = lista.length;
  if (tb) {
    var h = '';
    lista.forEach(function(a){
      h += '<tr>'
        + '<td style="font-weight:600;font-size:13px">'+esc2(a.Nombre_Actor||'')+'</td>'
        + '<td style="font-size:12px">'+esc2(_fmtDNI(a.DNI))+'</td>'
        + '<td style="font-size:12px">'+esc2(a.Telefono||a.telefono||'')+'</td>'
        + '<td style="font-size:12px">'+esc2(a.Email||a.email||'')+'</td>'
        + '<td style="font-size:12px">'+esc2(a.Institucion||a.Organizacion||'')+'</td>'
        + '<td style="font-size:11px">'+_deptNm(a.ID_Ubigeo||'')+'</td>'
      + '</tr>';
    });
    tb.innerHTML = h || '<tr><td colspan="6" style="text-align:center;padding:20px;color:#999">Sin resultados</td></tr>';
  }
}
function _reporteContacto(formato) {
  var lista = window._contactoFiltrado || [];
  var ids = lista.map(function(a){ return a.ID_Actor; }).filter(Boolean);
  if (!ids.length) { toast('No hay actores que coincidan con los filtros','err'); return; }
  toast('\u23F3 Generando reporte de contacto ('+ids.length+' actores)...');
  google.script.run.withSuccessHandler(function(r){
    if (r && r.ok && r.url) { window.open(r.url,'_blank'); toast('\u2705 Reporte generado'); }
    else toast(r && r.msg || 'Error al generar','err');
  }).withFailureHandler(function(e){ toast('Error: '+String(e),'err'); }).generarReporteDatosActores(ids, formato);
}

