function cargarActoresEstado() {
  var div = document.getElementById('actoresEstadoContent');
  if (!div) return;
  div.innerHTML = '<div class="spinner-wrap"><div class="spinner"></div><p>Cargando...</p></div>';
  // Los actores del Estado viven en DIM_Actores_Estado (CACHE.actoresEstado)
  function render() {
    var actores = CACHE.actoresEstado || [];
    renderActoresEstadoMod(actores);
    setTimeout(function() {
      _asegurarDeptos('fae_ubigeo', '');
      _asegurarAreas('fae_area', '');
    }, 100);
  }
  if (CACHE.actoresEstado && CACHE.actoresEstado.length) {
    render();
  } else {
    google.script.run.withSuccessHandler(function(r) {
      if (r && r.ok) CACHE.actoresEstado = r.data;
      render();
    }).withFailureHandler(function() { render(); }).getActoresEstado();
  }
  // Also load areas if needed
  if (!CACHE.areasResp) {
    google.script.run.withSuccessHandler(function(r) {
      if (r && r.ok) CACHE.areasResp = r.data;
    }).withFailureHandler(function(){}).getAreasResponsables();
  }
}
function renderActoresEstadoMod(actores) {
  var div = document.getElementById('actoresEstadoContent');
  if (!div) return;
  var rows = (actores || []).map(function(a) {
    var fotoUrl = a['Fotograf\u00EDa'] || a.Fotografia || '';
    var ft = fotoUrl
      ? '<img src="' + esc2(_driveImg(fotoUrl)) + '" style="width:34px;height:34px;border-radius:50%;object-fit:cover">'
      : '<div style="width:34px;height:34px;border-radius:50%;background:var(--bp);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:13px">' + String((a.Nombre_Actor||'?')[0]).toUpperCase() + '</div>';
    var aid = esc2(String(a.ID_Actor_Estado||a.ID_Actor||''));
    return '<tr>' +
      '<td>' + ft + '</td>' +
      '<td><strong>' + esc2(a.Nombre_Actor||'') + '</strong></td>' +
      '<td style="font-size:12px">' + esc2(_fmtDNI(a.DNI)) + '</td>' +
      '<td style="font-size:12px">' + esc2(a.Email||'') + '</td>' +
      '<td style="font-size:12px">' + esc2(a.Cargo||'') + '</td>' +
      '<td style="font-size:12px">' + esc2(_areaNm(a.Institucion||a.ID_Area||'')) + '</td>' +
      '<td style="font-size:12px">' + esc2(a.Nivel_Gobierno||'') + '</td>' +
      '<td style="font-size:12px">' + _deptNm(a.ID_Ubigeo||'') + '</td>' +
      '<td><span class="badge ' + (String(a.Activo||'').toLowerCase()==='s\u00ED'||String(a.Activo||'').toLowerCase()==='si'?'b-grn':'b-red') + '">' + (String(a.Activo||'').toLowerCase()==='s\u00ED'||String(a.Activo||'').toLowerCase()==='si'?'Activo':'Inactivo') + '</span></td>' +
      '<td><div class="t-act">' +
        '<button class="btn-ico" onclick="verPerfilActorEstado(\'' + aid + '\')" title="Ver perfil">&#x1F441;</button>' +
        '<button class="btn-ico" onclick="editarActorEstado(\'' + aid + '\')" title="Editar">&#x270F;</button>' +
        '<button class="btn-ico del" onclick="eliminarActorEstadoConf(\'' + aid + '\')" title="Eliminar">&#x1F5D1;</button>' +
      '</div></td>' +
      '</tr>';
  }).join('');
  var empty = '<tr><td colspan="11" style="text-align:center;padding:20px;color:var(--g500)">Sin actores del Estado registrados</td></tr>';
  div.innerHTML =
    '<div class="tabs" id="actEstTabs">' +
      '<button class="tb on" onclick="sTab(\'actoresEstado\',\'lista\',this)">Lista</button>' +
      '<button class="tb" onclick="sTab(\'actoresEstado\',\'nuevo\',this);_cargarEntidadesCascada()">+ Nuevo</button>' +
    '</div>' +
    '<div class="tpane on" id="actoresEstado-lista">' +
      '<div class="sc"><div class="sc-head"><h3>Actores del Estado &mdash; ' + (actores||[]).length + '</h3>' +
        '<button class="btn bxl btn-sm" onclick="exportCSV(\'tblActEst\',\'Actores_Estado\')">&#x2B07; Excel</button>' +
      '</div>' +
      '<div class="fbar" style="margin-bottom:8px"><input type="text" id="fAEq" placeholder="Buscar por nombre, cargo, entidad..." style="width:280px;font-size:12px" onkeyup="_filtrarTablaSimple(\'tblActEst\',this.value)"></div>' + '<div class="tw"><table id="tblActEst"><thead><tr>' +
        '<th>Foto</th><th>Nombre</th><th>DNI</th><th>Email</th><th>Cargo</th>' +
        '<th>\u00C1rea Responsable</th><th>Nivel</th><th>Depto.</th><th>Estado</th><th>Acc.</th>' +
      '</tr></thead><tbody>' + (rows || empty) + '</tbody></table></div></div>' +
    '</div>' +
    '<div class="tpane" id="actoresEstado-nuevo">' +
      renderFormActorEstado() +
    '</div>';
}
