function _agregarDemandaEditAlerta(idAlerta) {
  var elTipo = document.getElementById('ea_dem_tipo');
  var elDesc = document.getElementById('ea_dem_desc');
  var desc = elDesc ? elDesc.value.trim() : '';
  if (!desc) { toast('Ingrese la descripcion de la demanda', 'err'); return; }
  var demanda = { ID_Tematica: elTipo ? elTipo.value : '', desc: desc, Descripcion_Demanda: desc };
  toast('\u23F3 Guardando demanda...');
  google.script.run.withSuccessHandler(function(r){
    if (r && r.ok) {
      toast('\u2705 Demanda agregada');
      if (elDesc) elDesc.value = '';
      _cargarDemandasEditAlerta(idAlerta);
    } else toast(r && r.msg || 'Error', 'err');
  }).withFailureHandler(function(e){ toast('Error: '+String(e), 'err'); }).guardarDemandasAlerta(idAlerta, [demanda]);
}

