function guardarEdicionAlerta(idAlerta) {
  function gv(id){ var el=document.getElementById(id); return el?el.value.trim():''; }
  var datos = {
    ID_Alerta: idAlerta,
    Titulo_Alerta: gv('ea_titulo'),
    Fecha: gv('ea_fecha'),
    ID_Ubigeo: gv('ea_depto'),
    ID_Provincia: gv('ea_prov'),
    ID_Distrito: gv('ea_dist'),
    ID_Sector: gv('ea_sector'),
    ID_Nivel_Alerta: gv('ea_nivel'),
    ID_Riesgos: gv('ea_riesgo'),
    Situacion_Actual: gv('ea_sitActual'),
    Hechos_Recientes: gv('ea_hechos'),
    Descripcion_Riesgo: gv('ea_descRiesgo'),
    Acciones_sugeridas: gv('ea_acciones'),
    Acciones_OAIPCS: gv('ea_acciones_oaipcs'),
    ID_Caso_Vinculado: gv('ea_caso'),
    ID_MesaGrupo: gv('ea_mesaGrupo'),
    Sectorista: gv('ea_sectorista'),
    Estado: gv('ea_estado')
  };
  if (!datos.Titulo_Alerta) { toast('Ingrese el titulo de la alerta', 'err'); return; }
  toast('\u23F3 Guardando cambios...');
  google.script.run.withSuccessHandler(function(r){
    if (r && r.ok) {
      toast('\u2705 Alerta actualizada');
      cerrarModal();
      CACHE.alertas = null;
      cargarAlertas();
    } else toast(r && r.msg || 'Error', 'err');
  }).withFailureHandler(function(e){ toast('Error: '+String(e), 'err'); }).actualizarAlerta(datos);
}

