try {
  [100,300,600,1200,2000].forEach(function(ms){
    setTimeout(function(){ try{ _marcaAVISA(); _marcaAVISAHeader(); }catch(e){} }, ms);
  });
  // Observador: re-aplica marca cuando cambia el DOM (menus dinamicos)
  if (window.MutationObserver && document.body) {
    var _obsAvisa = new MutationObserver(function(){ try{ _marcaAVISA(); }catch(e){} });
    _obsAvisa.observe(document.body, { childList:true, subtree:true });
    setTimeout(function(){ try{ _obsAvisa.disconnect(); }catch(e){} }, 8000);
  }
} catch(e) {}
